## The gothic theme: black stone, gilt fillets, parchment ink.
##
## The structure mirrors `beyond`'s gothic theme (`~/Workspace/beyond`,
## src/beyond/gothic.nim): the same compact type scale, chiselled metrics
## and bronze scrollbar, but the corners are cut perfectly square - stone
## does not round like paper - and the palette's colours are generated by
## wallust from the live wallpaper. The renderer reads them from
## `~/.cache/wallust/nomicon-theme.conf` (`nomicon-theme.conf.j2` in the
## desktop module's wallust templates), re-reading whenever the file
## changes, so a wallpaper switch repaints a running nomicon on its next
## frame. Missing file, missing keys or a fresh install fall back to the
## built-in bronze-and-parchment palette below, the same one the game
## ships with.

import std/[os, strutils, tables]
import ellipse_ui

const wallustThemePath* = "~/.cache/wallust/nomicon-theme.conf"

# --- colour plumbing ----------------------------------------------------------

func hexColor(s: string): Color =
  ## `#rgb`, `#rrggbb` and `#rrggbbaa` wallust values. A failed parse
  ## returns a fully transparent colour, which the lookup below treats as
  ## absent, so typos cannot blank a widget.
  var h = s.strip
  if h.startsWith('#'): h = h[1..^1]
  template byte(x: string): float32 = float32(parseHexInt(x))
  try:
    case h.len
    of 3: rgb(byte(h[0..0] & h[0..0]), byte(h[1..1] & h[1..1]),
              byte(h[2..2] & h[2..2]))
    of 6: rgb(byte(h[0..1]), byte(h[2..3]), byte(h[4..5]))
    of 8: rgb(byte(h[0..1]), byte(h[2..3]), byte(h[4..5]), byte(h[6..7]))
    else: Color()
  except ValueError:
    Color()

func withAlpha(c: Color, a: float32): Color =
  Color(r: c.r, g: c.g, b: c.b, a: a)

func mix(a, b: Color, t: float32): Color =
  ## `a` pulled `t` of the way toward `b` (0 keeps `a`, 1 gives `b`).
  rgb(a.r + (b.r - a.r) * t,
      a.g + (b.g - a.g) * t,
      a.b + (b.b - a.b) * t,
      a.a + (b.a - a.a) * t)

# --- the wallust colour cache -------------------------------------------------
#
# A flat `key = #rrggbb` file, keys prefixed `dark.` or `light.`; comment
# lines (what the alatar seed and a "no theme yet" placeholder are made of)
# and unknown keys are ignored. The file is re-read every frame but only
# reparsed when its text differs from last time - cheap enough for the
# immediate-mode loop, and it catches a wallpaper switch without a hook.

var cachedText: string
var cachedColors: Table[string, Color]

proc wallustColors(): Table[string, Color] =
  let path =
    if wallustThemePath.startsWith("~/"):
      getHomeDir() / wallustThemePath[2..^1]
    else: wallustThemePath
  let text =
    if fileExists(path):
      try: readFile(path) except CatchableError: ""
    else: ""
  if text != cachedText:
    cachedText = text
    cachedColors = initTable[string, Color]()
    for line in text.splitLines:
      let entry = line.strip
      if entry.len == 0 or entry.startsWith('#'): continue
      let eq = find(entry, '=')
      if eq < 0: continue
      let color = hexColor(entry[(eq + 1)..^1])
      if color.a > 0:
        cachedColors[entry[0..<eq].strip] = color
  cachedColors

func color(c: Table[string, Color], prefix, role: string, fallback: Color): Color =
  let found = c.getOrDefault(prefix & "." & role)
  if found.a == 0: fallback else: found

# --- the built-in gothic palette (the beyond one) ------------------------------
#
# What nomicon ships with while wallust has generated nothing yet: the void,
# an obsidian slab, aged bronze fillets, consecrated red, parchment ink.

func gothicDarkPalette(): Palette =
  Palette(
    bg: rgb(2, 2, 3),                    # the void behind everything
    panelBg: rgb(15, 13, 17),            # obsidian slab
    panelBorder: rgb(112, 92, 58),       # aged bronze fillet
    buttonBg: rgb(30, 26, 32),           # raised stone
    buttonHoverBg: rgb(62, 50, 34),      # bronze lit by torchlight
    buttonPressBg: rgb(8, 7, 9),         # sunk into the slab
    fieldBg: rgb(6, 6, 8),               # sunken groove
    selectedBg: rgb(74, 58, 30),         # gilt choice
    accent: rgb(146, 42, 38),            # consecrated blood red
    textColor: rgb(214, 202, 178),       # parchment ink
    dimColor: rgb(110, 102, 88),         # faded vellum
    labelColor: rgb(168, 154, 130),      # candle-lit vellum
    onAccent: rgb(238, 228, 205),        # pale ink on the red seal
    shadow: rgb(0, 0, 0, 150),           # deep drop behind popovers
  )

func gothicLightPalette(): Palette =
  ## The same hall cut in vellum: a gilt band around a parchment face,
  ## ink dark enough to read at candlelight.
  Palette(
    bg: rgb(210, 197, 170),              # the vellum behind everything
    panelBg: rgb(228, 218, 196),         # fresh parchment
    panelBorder: rgb(112, 92, 58),       # aged bronze fillet
    buttonBg: rgb(196, 183, 156),        # pressed card
    buttonHoverBg: rgb(150, 126, 84),    # bronze in daylight
    buttonPressBg: rgb(172, 158, 131),   # dented card
    fieldBg: rgb(242, 236, 222),         # bleached sheet
    selectedBg: rgb(176, 150, 96),       # gilt choice
    accent: rgb(122, 34, 30),            # consecrated blood red, inked
    textColor: rgb(38, 30, 22),          # iron-gall ink
    dimColor: rgb(110, 100, 82),         # faded note
    labelColor: rgb(74, 64, 50),         # secondary ink
    onAccent: rgb(238, 228, 205),        # pale ink on the red seal
    shadow: rgb(60, 50, 32, 90),         # soft drop behind popovers
  )

# --- theme pieces ---------------------------------------------------------------

proc gothicPalette(dark: bool): Palette =
  let c = wallustColors()
  let p = if dark: "dark" else: "light"
  let d = if dark: gothicDarkPalette() else: gothicLightPalette()
  result = d
  result.bg = color(c, p, "bg", d.bg)
  result.panelBg = color(c, p, "panel_bg", d.panelBg)
  result.panelBorder = color(c, p, "panel_border", d.panelBorder)
  result.buttonBg = color(c, p, "button_bg", d.buttonBg)
  result.buttonHoverBg = color(c, p, "button_hover_bg", d.buttonHoverBg)
  result.buttonPressBg = color(c, p, "button_press_bg", d.buttonPressBg)
  result.fieldBg = color(c, p, "field_bg", d.fieldBg)
  result.selectedBg = color(c, p, "selected_bg", d.selectedBg)
  result.accent = color(c, p, "accent", d.accent)
  result.textColor = color(c, p, "text_color", d.textColor)
  result.dimColor = color(c, p, "dim_color", d.dimColor)
  result.labelColor = color(c, p, "label_color", d.labelColor)
  result.onAccent = color(c, p, "on_accent", d.onAccent)
  # The shadow and the scrollbar are not palette slots of their own here:
  # the drop is the void itself, the bar is the fillet lit and sunk (see
  # gothicScrollbar).
  result.shadow = if dark: rgb(0, 0, 0, 150) else: d.shadow

func gothicTextSizes(): TextSizes =
  TextSizes(
    h1: 34, h2: 26, h3: 21, h4: 17, h5: 15, h6: 14,
    button: 15, menu: 14, control: 14, option: 13, chevron: 12,
    cardTitle: 15, statLabel: 12, statValue: 22, statHint: 11,
    label: 12, caption: 11, overline: 10, badge: 10,
  )

func gothicRadii(): Radii =
  ## Square cuts only: stone, not paper. Every corner in the widget set
  ## resolves to zero radius through these tokens.
  Radii(
    button: 0.0, field: 0.0, check: 0.0, tick: 0.0, inner: 0.0,
    item: 0.0, panel: 0.0,
    popover: 0.0, popoverShadow: 0.0, tab: 0.0, tabPanel: 0.0,
    card: 0.0, pill: 0.0, switch: 0.0, switchKnob: 0.0,
  )

func gothicMetrics(): Metrics =
  Metrics(
    controlHeight: 30.0, toolbarHeight: 38.0,
    checkSize: 16.0, tickSize: 8.0, checkSizeSm: 15.0, tickSizeSm: 7.0,
    switchWidth: 36.0, switchHeight: 20.0, switchKnob: 14.0,
    stepperSize: 22.0,
    listMaxHeight: 240.0, multiListMaxHeight: 260.0,
    textRowHeight: 18.0, popoverOffset: 6.0,
    padButton: 6, padMenuItem: 7, padOption: 5, padList: 4,
    padFieldX: 8, padFieldY: 5, padCheckRow: 3, padCard: 14, padStat: 10,
    padPanel: 10, padToolbar: 4, padSwitch: 3, padTabX: 12, padTabTop: 6,
    padTabBottom: 5, padMinor: 4, padItem: 6,
    gapCard: 10, gapCardRow: 12, gapProse: 8, gapTight: 6, gapList: 2,
    borderRaised: 2, borderHairline: 1, borderTab: 2, pressOffset: 1,
    headingPadH1: 6, headingPadH2: 10, headingPadH3: 8,
    headingPadMinor: 8, headingPadBottom: 5,
  )

proc gothicScrollbar(dark: bool): ScrollbarStyle =
  let t = if dark: gothicDarkPalette() else: gothicLightPalette()
  let c = wallustColors()
  let gilt = color(c, if dark: "dark" else: "light", "panel_border", t.panelBorder)
  let void = color(c, if dark: "dark" else: "light", "bg", t.bg)
  ScrollbarStyle(
    width: 10.0, margin: 4.0, radius: 0.0, minThumb: 28.0,
    track: withAlpha(mix(gilt, void, 0.55), 60),
    thumb: withAlpha(gilt, 190),
    thumbHot: withAlpha(mix(gilt, t.textColor, 0.3), 235))

proc gothicTheme*(dark: bool): Theme =
  ## The live gothic look: beyond's structure, wallust's colours.
  Theme(
    palette: gothicPalette(dark),
    text: gothicTextSizes(),
    radii: gothicRadii(),
    metrics: gothicMetrics(),
    scrollbar: gothicScrollbar(dark),
    cells: defaultCellLook(),
  )
